import { readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const styles = readFileSync(join(root, 'styled-system/styles.css'), 'utf8');
const theme = readFileSync(join(root, 'theme-base.css'), 'utf8');

const header = `/**
 * Generated by scripts/bundle-css.mjs — do not edit by hand.
 * Contains Panda styles.css + theme-base.css (no CSS @import).
 *
 * Prefer:
 *   import '@becket-ui/tokens/index.css';
 *
 * Advanced (utilities only):
 *   import '@becket-ui/tokens/styles.css';
 */

`;

writeFileSync(join(root, 'index.css'), `${header}${styles}\n${theme}\n`);
console.log('Wrote index.css (styles + theme-base)');
